import { Component, Event, EventEmitter, Host, Prop, h } from '@stencil/core';
import { LinkVariant, LinkWeight, Rel, Target } from '../../types';
import { verifyTarget } from '../../utils/link-helper';

/**
 * @slot default - default slot for the content of the hyperlink
 */
@Component({
  tag: 'groupui-link',
  styleUrl: 'link.scss',
  shadow: true,
})
export class Link {
  /**
   * activates an inverted presentation
   */
  @Prop({ reflect: true }) readonly inverted: boolean;

  /**
   * activates a quiet presentation without underline
   */
  @Prop({ reflect: true }) readonly quiet: boolean;

  /**
   * variant of the link
   */
  @Prop({ reflect: true }) readonly variant: LinkVariant = 'primary';

  /**
   * weight of the link
   */
  @Prop({ reflect: true }) readonly weight: LinkWeight = 'regular';

  /**
   * URL that the hyperlink points to. Examples: https://www.volkswagen.de/ - tel:05361/12345 - mailto:john.doe@example.com - #anchor1
   */
  @Prop({ reflect: true }) readonly href: string;

  /**
   * where to display the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * in which relation is the linked URL to the current page
   */
  @Prop({ reflect: true }) readonly rel: Rel;

  /**
   * icon name for an icon placed left to the text e.g. 'chevron-left-24'. Use the icon size m: 24px
   */
  @Prop({ reflect: true }) readonly iconLeft: string;

  /**
   * sets a custom icon source e.g. '...path/chevron-left-24.svg', overrides icon-left property if both are set
   */
  @Prop({ reflect: true }) readonly iconLeftSource: string;

  /**
   * icon name for an icon placed right to the text e.g. 'chevron-right-24'. Use the icon size m: 24px
   */
  @Prop({ reflect: true }) readonly iconRight: string;

  /**
   * sets a custom icon source e.g. '...path/chevron-left-24.svg', overrides icon-right property if both are set
   */
  @Prop({ reflect: true }) readonly iconRightSource: string;

  /**
   * truncates the link when content is larger than wrapping element
   */
  @Prop({ reflect: true }) readonly truncate: boolean;

  /**
   * indicates that the linked resource is to be downloaded rather than displayed in the browser
   */
  @Prop({ reflect: true }) readonly download: string;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private getLeftIcon() {
    if (!this.iconLeft && !this.iconLeftSource) return;
    return <groupui-icon class="icon-left" name={this.iconLeft} src={this.iconLeftSource} aria-hidden="true" />;
  }

  private getRightIcon() {
    if (!this.iconRight && !this.iconRightSource) return;
    return <groupui-icon class="icon-right" name={this.iconRight} src={this.iconRightSource} aria-hidden="true" />;
  }

  render() {
    return (
      <Host>
        <a tabIndex={0} href={this.href} target={verifyTarget(this.target)} rel={this.rel} download={this.download}>
          {this.getLeftIcon()}
          <slot></slot>
          {this.getRightIcon()}
        </a>
      </Host>
    );
  }
}
